def mapper_wordcount(doc_id: str, text: str) -> list:
    intermediate = []
    for raw_word in text.split():
        clean_word = raw_word.lower().strip('.,!?:;"\'()[]{}')
        if clean_word:
            intermediate.append((clean_word, 1))
    return intermediate

def reducer_sum(word: str, counts: list) -> tuple:
    return (word, sum(counts))

def run_mapreduce(documents: dict) -> dict:
    # 1. Map Phase
    all_mapped = []
    for doc_id, text in documents.items():
        all_mapped.extend(mapper_wordcount(doc_id, text))

    # 2. Shuffle & Sort Phase (Group by Key)
    grouped = {}
    for word, count in all_mapped:
        grouped.setdefault(word, []).append(count)

    # 3. Reduce Phase
    final_output = {}
    for word, counts in sorted(grouped.items()):
        w, total = reducer_sum(word, counts)
        final_output[w] = total

    return final_output

